#[test]
fn byte_identity_round_trip() {
    let manifest = read_json("manifest.json");
    let entries = manifest["embedding"].as_array().expect("embedding");
    assert_eq!(entries.len(), 6, "one fixture per embedding record");
    for entry in entries {
        let file = entry["file"].as_str().unwrap();
        let field = entry["field"].as_str().unwrap();
        match entry["record"].as_str().unwrap() {
            "InitRequest" => {
                assert_eq!(field, "bind_call");
                check_embedding::<InitRequest>(
                    file,
                    field,
                    init_request_bind_call,
                    InitRequest::bind_call_value,
                )
            }
            "TableFunctionCardinalityRequest" => {
                assert_eq!(field, "bind_call");
                check_embedding::<TableFunctionCardinalityRequest>(
                    file,
                    field,
                    table_function_cardinality_request_bind_call,
                    TableFunctionCardinalityRequest::bind_call_value,
                )
            }
            "TableFunctionStatisticsRequest" => {
                assert_eq!(field, "bind_call");
                check_embedding::<TableFunctionStatisticsRequest>(
                    file,
                    field,
                    table_function_statistics_request_bind_call,
                    TableFunctionStatisticsRequest::bind_call_value,
                )
            }
            "TableFunctionDynamicToStringRequest" => {
                assert_eq!(field, "bind_call");
                check_embedding::<TableFunctionDynamicToStringRequest>(
                    file,
                    field,
                    table_function_dynamic_to_string_request_bind_call,
                    TableFunctionDynamicToStringRequest::bind_call_value,
                )
            }
            "TableFunctionPlanRequest" => {
                assert_eq!(field, "bind_call");
                check_embedding::<TableFunctionPlanRequest>(
                    file,
                    field,
                    table_function_plan_request_bind_call,
                    TableFunctionPlanRequest::bind_call_value,
                )
            }
            "TableFunctionProjectionRequest" => {
                assert_eq!(field, "bind_call");
                check_embedding::<TableFunctionProjectionRequest>(
                    file,
                    field,
                    table_function_projection_request_bind_call,
                    TableFunctionProjectionRequest::bind_call_value,
                )
            }
            other => {
                panic!("manifest names an embedding record this SDK does not generate: {other}")
            }
        }
    }
}

#[test]
fn decode_errors_surface_at_access_with_the_field_path() {
    let record = InitRequest {
        bind_call: Nested::from_bytes(&b"not arrow"[..]),
        output_schema: Bytes(Vec::new()),
        bind_opaque_data: None,
        projection_ids: None,
        pushdown_filters: None,
        join_keys: None,
        split_tokens: None,
        row_limit: None,
        phase: None,
        finalize_state_id: None,
        execution_id: None,
        init_opaque_data: None,
        substream_id: None,
        order_by_column_name: None,
        order_by_direction: None,
        order_by_null_order: None,
        order_by_limit: None,
        tablesample_percentage: None,
        tablesample_seed: None,
    };
    let decoded: InitRequest = decode(&encode(record));
    let err = decoded
        .bind_call_value()
        .expect_err("garbage must not decode");
    assert!(
        err.message.contains("InitRequest.bind_call"),
        "{}",
        err.message
    );
    let empty: Nested<BindRequest> = Nested::from_bytes(Vec::new());
    assert!(
        empty.get().is_err(),
        "an empty nested value is a decode error at access"
    );
}

#[test]
fn typed_construction_round_trips() {
    let bind = BindRequest {
        function_name: "typed_construction".to_string(),
        arguments: Some(Bytes(vec![1, 2, 3])),
        function_type: DictString("TABLE".to_string()),
        input_schema: None,
        settings: None,
        secrets: None,
        attach_opaque_data: Some(Bytes(b"attach".to_vec())),
        transaction_opaque_data: None,
        resolved_secrets_provided: true,
        at_unit: Some("VERSION".to_string()),
        at_value: None,
        copy_from: None,
        copy_to: None,
        schema_path: Some(vec!["main".to_string(), "s".to_string()]),
        argument_names: Some(vec![Some("a".to_string()), None]),
        arguments_location: None,
    };
    let wrapped = Nested::from_record(bind.clone()).expect("serialize");
    let init = InitRequest {
        bind_call: wrapped.clone(),
        output_schema: Bytes(b"schema".to_vec()),
        bind_opaque_data: None,
        projection_ids: None,
        pushdown_filters: None,
        join_keys: None,
        split_tokens: None,
        row_limit: Some(10),
        phase: None,
        finalize_state_id: None,
        execution_id: None,
        init_opaque_data: None,
        substream_id: None,
        order_by_column_name: None,
        order_by_direction: None,
        order_by_null_order: None,
        order_by_limit: None,
        tablesample_percentage: None,
        tablesample_seed: None,
    };
    let first = encode(init.clone());
    let second = encode(init);
    assert_eq!(first, second, "encoding the same wrapper twice");
    let decoded: InitRequest = decode(&first);
    assert_eq!(
        decoded.bind_call.bytes(),
        wrapped.bytes(),
        "held bytes survive"
    );
    let got = decoded.bind_call_value().expect("access");
    assert_eq!(
        record_json(got.clone()),
        record_json(bind.clone()),
        "fields equal"
    );
    assert_eq!(got.function_name, "typed_construction");
    assert_eq!(
        Nested::from_record(bind).expect("serialize").bytes(),
        wrapped.bytes(),
        "serializing the same record is deterministic",
    );
}

#[test]
fn null_arguments_and_exactly_one() {
    let manifest = read_json("manifest.json");
    for entry in manifest["binds"].as_array().expect("binds") {
        let file = entry["file"].as_str().unwrap();
        let bind: BindRequest = decode(&read(file));
        if entry["valid"].as_bool().unwrap() {
            assert!(
                bind.arguments.is_none(),
                "{file}: arguments must decode as None, not empty"
            );
            let location = bind
                .arguments_location
                .as_ref()
                .expect("arguments_location");
            let want = &entry["arguments_location"];
            assert_eq!(
                hex(&location.r#ref.0),
                want["ref"]["hex"].as_str().unwrap(),
                "{file}: ref"
            );
            assert_eq!(
                location.size,
                want["size"].as_i64().unwrap(),
                "{file}: size"
            );
            assert_eq!(
                location.sha256,
                want["sha256"].as_str().unwrap(),
                "{file}: sha256"
            );
            bind.validate_arguments()
                .unwrap_or_else(|e| panic!("{file}: {e}"));
            assert_fields(&bind, &entry["fields"], file);
        } else {
            let err = bind.validate_arguments().expect_err(file);
            assert_eq!(
                err.error_kind(),
                entry["error_kind"].as_str().unwrap(),
                "{file}: kind"
            );
            assert_eq!(err.code(), Code::InvalidArgument, "{file}: code");
            assert_eq!(
                err.message,
                manifest["error_message"].as_str().unwrap(),
                "{file}: message"
            );
        }
    }
}
